-- ods.order_pay: 2/6 列脱敏
CREATE OR REPLACE VIEW ods.order_pay_masked AS
SELECT
  order_id,
  user_id,
  concat('************', substr(bank_card_no, -4)) AS bank_card_no  -- bank_card · high,
  amount,
  concat(substr(lianxi, 1, 3), '****', substr(lianxi, -4)) AS lianxi  -- phone · high,
  dt
FROM ods.order_pay;

-- ods.user_info: 5/8 列脱敏
CREATE OR REPLACE VIEW ods.user_info_masked AS
SELECT
  user_id,
  concat(substr(user_name, 1, 1), '**') AS user_name  -- person_name · high,
  concat(substr(phone, 1, 3), '****', substr(phone, -4)) AS phone  -- phone · high,
  concat(substr(id_card_no, 1, 6), '********', substr(id_card_no, -4)) AS id_card_no  -- id_card · high,
  concat(substr(email, 1, 1), '***', substr(email, instr(email, '@'))) AS email  -- email · high,
  concat(substr(home_addr, 1, 6), '****') AS home_addr  -- address · high,
  reg_time,
  dt
FROM ods.user_info;

